import fnmatch
def decision(policy,action,resource):
    if not isinstance(policy,dict) or set(policy)-{'Version','Statement'} or not isinstance(policy.get('Statement'),list):raise ValueError('finite identity policy')
    effects=[]
    for statement in policy['Statement']:
        if not isinstance(statement,dict) or set(statement)-{'Sid','Effect','Action','Resource'} or statement.get('Effect') not in ('Allow','Deny'):raise ValueError('unsupported statement')
        actions=statement.get('Action');resources=statement.get('Resource')
        actions=actions if isinstance(actions,list) else [actions];resources=resources if isinstance(resources,list) else [resources]
        if not actions or not resources or any(not isinstance(x,str) or not x or '[' in x or ']' in x or '${' in x for x in actions+resources):raise ValueError('finite glob patterns')
        if any(fnmatch.fnmatchcase(action.lower(),pattern.lower()) for pattern in actions) and any(fnmatch.fnmatchcase(resource,pattern) for pattern in resources):effects.append(statement['Effect'])
    return 'explicit-deny' if 'Deny' in effects else 'allow' if 'Allow' in effects else 'implicit-deny'

