import re
def can_assume(caller_policy,trust,caller,role):
    pattern=r'arn:(?:aws|aws-cn|aws-us-gov):iam::[0-9]{12}:role/[A-Za-z0-9+=,.@_/-]+'
    if any(not isinstance(x,str) or not re.fullmatch(pattern,x) for x in (caller,role)) or caller.split(':')[4]==role.split(':')[4]:raise ValueError('cross-account role ARNs')
    if not isinstance(trust,dict) or set(trust)-{'Version','Statement'} or not isinstance(trust.get('Statement'),list):raise ValueError('finite trust document')
    identity=decision(caller_policy,'sts:AssumeRole',role)
    effects=[]
    for statement in trust['Statement']:
        if set(statement)-{'Sid','Effect','Action','Principal'} or statement.get('Effect') not in ('Allow','Deny') or set(statement.get('Principal',{}))!={'AWS'}:raise ValueError('finite trust policy')
        principals=statement['Principal']['AWS'];principals=principals if isinstance(principals,list) else [principals]
        actions=statement.get('Action');actions=actions if isinstance(actions,list) else [actions]
        if any(not isinstance(x,str) or not re.fullmatch(pattern,x) for x in principals) or any(not isinstance(x,str) for x in actions):raise ValueError('exact role principals only')
        if caller in principals and any(x.lower()=='sts:assumerole' for x in actions):effects.append(statement['Effect'])
    if identity=='explicit-deny' or 'Deny' in effects:return 'explicit-deny'
    return 'allow' if identity=='allow' and 'Allow' in effects else 'implicit-deny'
